import { expect, expectStatus, test, uniqueName, type APIRequestContext } from "../../fixtures";

type DocumentKind = "w9" | "insurance_certificate" | "contract";
const DOCUMENT_KINDS: DocumentKind[] = ["w9", "insurance_certificate", "contract"];

interface VendorBody {
  id: string;
  status: string;
}

interface DocumentBody {
  id: string;
  kind: DocumentKind;
  status: string;
}

/** Polls a document until extraction finishes, failing fast if extraction fails. */
async function waitForExtracted(api: APIRequestContext, documentId: string): Promise<void> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const body = await expectStatus<DocumentBody>(await api.get(`/api/documents/${documentId}`), 200);
    if (body.status === "extracted") return;
    if (body.status === "failed") throw new Error(`extraction failed for document ${documentId}`);
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`document ${documentId} was not extracted in time`);
}

test.describe("submit vendor for review", () => {
  test(
    "submitting a vendor with all documents extracted moves it to in_review and records an audit event",
    { tag: "@REV-01" },
    async ({ apiAs }) => {
      // Arrange: a member creates a draft vendor with a unique name.
      const member = await apiAs("member");
      const vendor = await expectStatus<VendorBody>(
        await member.post("/api/vendors", {
          data: {
            name: uniqueName("REV-01 Vendor"),
            category: "services",
            contact_email: "billing@rev01.example.test",
          },
        }),
        201,
      );
      expect(vendor.status).toBe("draft");

      // Arrange: upload one of each required document kind and wait for extraction.
      for (const kind of DOCUMENT_KINDS) {
        const document = await expectStatus<DocumentBody>(
          await member.post(`/api/vendors/${vendor.id}/documents`, {
            multipart: {
              kind,
              file: {
                name: `${kind}.pdf`,
                mimeType: "application/pdf",
                buffer: Buffer.from("%PDF-1.4 REV-01 test document"),
              },
            },
          }),
          201,
        );
        await waitForExtracted(member, document.id);
      }

      // Act: submit the vendor for review.
      const response = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert: the submit response reports in_review.
      const submitted = await expectStatus<VendorBody>(response, 200);
      expect(submitted.id).toBe(vendor.id);
      expect(submitted.status).toBe("in_review");

      // Assert: the vendor's persisted status is in_review.
      const fetched = await expectStatus<VendorBody>(await member.get(`/api/vendors/${vendor.id}`), 200);
      expect(fetched.status).toBe("in_review");

      // Assert: the audit trail contains a vendor.submitted event.
      const audit = await expectStatus<{ items: { action: string }[] }>(
        await member.get(`/api/vendors/${vendor.id}/audit`),
        200,
      );
      expect(audit.items.map((event) => event.action)).toContain("vendor.submitted");
    },
  );
});
